self.KB_CONTENT["card:757062"]={"id":"card:757062","ty":"card","sourceId":"757062","title":"『成本開帳/調整單建立作業』中的『複檢日期 (TK020)』為何？","ver":"iGP","topic":"品號","keywords":["品號","異動","批號","單頭"],"y":"other","answer":"* 批號件時則推算日期為：複檢日期=單頭異動日期+品號基本資料檔之複檢天數，依萬年曆推算正確日期不管休假。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
