self.KB_CONTENT["card:779211"]={"id":"card:779211","ty":"card","sourceId":"779211","title":"『暫出/入單建立作業(IDL)』中的『專案代號 (TG018)』為何？","ver":"GP4以上","topic":"暫出入","keywords":["暫出入","品號","專案","入單"],"y":"other","answer":"* [F3]品號專案資料查詢(INVLD-01)。* [F2]專案代號資料查詢(CMSNB-02)。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
