self.KB_CONTENT["field:783889"]={"id":"field:783889","ty":"field","sourceId":"783889","title":"部門代號","ver":"GP4以上","topic":"","keywords":[],"job":"資產外送建立作業","code":"TG004","answer":"* [F2]部門資料查詢及[F3]部門資產查詢。輸入後自動顯示部門名稱。但不允許空白。* 當變動時清除保管人。","file":"fields.jsonl"};
